//! CP7 (Gall's-Law checkpoint plan) two-proof pattern applied to
//! `crates/ggen-lsp/src/generated_diagnostic_codes.rs`, the const table generated by
//! `ggen sync run` (rule `gen-diag-codes-rust` in root `ggen.toml`) from
//! `.specify/repo-facts.ttl`'s `rf:DiagnosticCode` individuals. CP7 closed
//! GGEN-TPL-001 and GGEN-OUT-001; this pass extends the same query/filter/test
//! shape (not a new generation setup) to close the remaining 3 of 5 codes CP7
//! explicitly left out: GGEN-YIELD-001, GGEN-RULE-001, GGEN-QUERY-002.
//!
//! Proof 1 (hand-transcribed): EXPECTED consts read directly from the REAL
//! `crates/ggen-lsp/src/analyzers/tera_analyzer.rs` doc comments/const definitions, not
//! from the ontology -- confirms the generated table matches the real analyzer code.
//!
//! Proof 2 (SPARQL-derived): re-queries `.specify/repo-facts.ttl` live, independently
//! shaped from the generation query in `ggen.toml` (selects ALL `rf:DiagnosticCode`
//! fields, not just `?order`, and filters on `?code` string containment instead of
//! `?order` equality) -- confirms the generated table matches the ontology.

use ggen_lsp::generated_diagnostic_codes::{DiagnosticCodeFact, GENERATED_DIAGNOSTIC_CODES};

/// Proof 1: hand-transcribed from `crates/ggen-lsp/src/analyzers/tera_analyzer.rs`'s real
/// doc comments/const definitions (lines 16-57, `GGEN_TPL_001` / `GGEN_OUT_001` /
/// `GGEN_YIELD_001` / `GGEN_RULE_001` / `GGEN_QUERY_002` consts) and their real
/// `DiagnosticSeverity` usage at each code's emission site: `yield_001_diagnostics`
/// (ERROR, line ~701), `unbound_rule_file_diagnostics` (ERROR, line ~639),
/// `select_star_diagnostics` (WARNING, line ~833).
const EXPECTED: &[DiagnosticCodeFact] = &[
    DiagnosticCodeFact {
        code: "GGEN-TPL-001",
        severity: "ERROR",
        meaning: "Template consumes `{{ var }}` that SELECT does not produce.",
        owner: "ggen-lsp/src/analyzers/tera_analyzer.rs",
    },
    DiagnosticCodeFact {
        code: "GGEN-OUT-001",
        severity: "ERROR",
        meaning: "`output_file` pattern consumes unbound variable.",
        owner: "ggen-lsp/src/analyzers/tera_analyzer.rs",
    },
    DiagnosticCodeFact {
        code: "GGEN-YIELD-001",
        severity: "ERROR",
        meaning: "`output_file` escapes the project root (Layer Violation).",
        owner: "ggen-lsp/src/analyzers/tera_analyzer.rs",
    },
    DiagnosticCodeFact {
        code: "GGEN-RULE-001",
        severity: "ERROR",
        meaning: "`{file = ...}` binding points at a missing file.",
        owner: "ggen-lsp/src/analyzers/tera_analyzer.rs",
    },
    DiagnosticCodeFact {
        code: "GGEN-QUERY-002",
        severity: "WARNING",
        meaning: "`SELECT *` used (disables provision checks).",
        owner: "ggen-lsp/src/analyzers/tera_analyzer.rs",
    },
];

#[test]
fn generated_table_matches_hand_transcribed_tera_analyzer_reality() {
    assert_eq!(
        GENERATED_DIAGNOSTIC_CODES, EXPECTED,
        "generated_diagnostic_codes.rs has drifted from the real tera_analyzer.rs code -- \
         re-run `ggen sync run` and/or re-transcribe EXPECTED from the real source"
    );
}

#[test]
fn generated_table_codes_are_the_real_analyzer_constants() {
    // Cross-check against the analyzer module's own exported consts, not just the
    // hand-transcribed literal above -- if `tera_analyzer.rs`'s const *values* ever
    // change, this catches it even if someone forgets to update EXPECTED too.
    use ggen_lsp::analyzers::tera_analyzer::{
        GGEN_OUT_001, GGEN_QUERY_002, GGEN_RULE_001, GGEN_TPL_001, GGEN_YIELD_001,
    };
    let codes: Vec<&str> = GENERATED_DIAGNOSTIC_CODES.iter().map(|f| f.code).collect();
    assert_eq!(
        codes,
        vec![
            GGEN_TPL_001,
            GGEN_OUT_001,
            GGEN_YIELD_001,
            GGEN_RULE_001,
            GGEN_QUERY_002,
        ]
    );
}

/// Proof 2: SPARQL-derived, independently shaped from the generation query. The
/// generation rule in `ggen.toml` selects `?order` (to drive `skip_empty`, filtered to
/// orders 001-005); this query instead selects every field directly and filters on
/// `?code` string containment instead of `?order` equality -- a different predicate
/// path through the same graph.
#[test]
fn sparql_derived_proof_reconfirms_the_five_rows_independently() {
    use oxigraph::io::RdfFormat;
    use oxigraph::sparql::{QueryResults, SparqlEvaluator};
    use oxigraph::store::Store;

    let ttl_path = concat!(env!("CARGO_MANIFEST_DIR"), "/../../.specify/repo-facts.ttl");
    let bytes = std::fs::read(ttl_path).expect("repo-facts.ttl must be readable");

    let store = Store::new().expect("in-memory oxigraph store");
    store
        .load_from_reader(RdfFormat::Turtle, bytes.as_slice())
        .expect("repo-facts.ttl must parse as valid Turtle");

    let sparql = r#"
        PREFIX rf: <http://ggen.org/repo-facts#>
        SELECT ?code ?severity ?meaning ?owner WHERE {
            ?diag a rf:DiagnosticCode ;
                  rf:code ?code ;
                  rf:severity ?severity ;
                  rf:meaning ?meaning ;
                  rf:owner ?owner .
            FILTER(
                CONTAINS(STR(?code), "GGEN-TPL-001") ||
                CONTAINS(STR(?code), "GGEN-OUT-001") ||
                CONTAINS(STR(?code), "GGEN-YIELD-001") ||
                CONTAINS(STR(?code), "GGEN-RULE-001") ||
                CONTAINS(STR(?code), "GGEN-QUERY-002")
            )
        } ORDER BY ?code
    "#;

    let query = SparqlEvaluator::new()
        .parse_query(sparql)
        .expect("query must parse");
    let results = query.on_store(&store).execute().expect("query must run");

    let mut rows: Vec<(String, String, String, String)> = Vec::new();
    if let QueryResults::Solutions(solutions) = results {
        for solution in solutions {
            let solution = solution.expect("solution binding must resolve");
            let get = |name: &str| -> String {
                solution
                    .get(name)
                    .expect("bound var")
                    .to_string()
                    .trim_matches('"')
                    .to_string()
            };
            rows.push((
                get("code").replace("**", ""),
                get("severity"),
                get("meaning"),
                get("owner").replace('`', ""),
            ));
        }
    } else {
        panic!("expected SELECT solutions");
    }

    assert_eq!(
        rows.len(),
        5,
        "expected exactly GGEN-TPL-001, GGEN-OUT-001, GGEN-YIELD-001, GGEN-RULE-001, \
         GGEN-QUERY-002: {rows:?}"
    );

    // Lexicographic ORDER BY ?code: OUT < QUERY < RULE < TPL < YIELD -- deliberately a
    // different row order than the generated table (which is ORDER BY ?order, i.e.
    // TPL, OUT, YIELD, RULE, QUERY), to prove this is a genuinely independent
    // re-derivation.
    assert_eq!(rows[0].0, "GGEN-OUT-001");
    assert_eq!(rows[1].0, "GGEN-QUERY-002");
    assert_eq!(rows[2].0, "GGEN-RULE-001");
    assert_eq!(rows[3].0, "GGEN-TPL-001");
    assert_eq!(rows[4].0, "GGEN-YIELD-001");

    for row in &rows {
        let generated = GENERATED_DIAGNOSTIC_CODES
            .iter()
            .find(|f| f.code == row.0)
            .unwrap_or_else(|| panic!("SPARQL found {} but generated table lacks it", row.0));
        assert_eq!(generated.severity, row.1);
        assert_eq!(generated.meaning, row.2);
        assert_eq!(generated.owner, row.3);
    }
}

/// Drift-injection-and-revert: prove the hand-transcribed proof actually refuses a
/// corrupted table, rather than vacuously passing regardless of content.
#[test]
fn hand_transcribed_proof_would_catch_a_deliberately_corrupted_severity() {
    let mut corrupted: Vec<DiagnosticCodeFact> = GENERATED_DIAGNOSTIC_CODES.to_vec();
    corrupted[4].severity = "ERROR"; // real value for GGEN-QUERY-002 is "WARNING"
    assert_ne!(
        corrupted.as_slice(),
        EXPECTED,
        "corrupted table must differ from EXPECTED -- if this fails, the proof is vacuous"
    );
    // ...and the real, on-disk generated table is untouched and still matches.
    assert_eq!(GENERATED_DIAGNOSTIC_CODES, EXPECTED);
}
